using System;using System.IO;using System.IO.Compression;using System.Linq;using System.Collections.Generic;using System.Reflection;using System.Security.Cryptography;using System.Text;using System.Diagnostics;using System.Threading;using System.Web.Script.Serialization;
[assembly:AssemblyTitle("NodNuat ACE COMBAT 8 Thai Setup 2.4")]
[assembly:AssemblyVersion("2.4.0.0")]
[assembly:AssemblyFileVersion("2.4.0.0")]
namespace THub.ACE8 {
public class Entry {public string path,sha256;public long bytes;public string[] known;}
public class Manifest {public int schema;public string version,exeHash,bootstrapHash,settingsHash;public long requiredSpace;public Entry[] files;}
public class Before {public string path,hash;public bool present;}
public class Pending {public int schema=1;public string root,action,transaction,previousReceipt;public Before[] before;public string settingsHash;}
public static class Engine {
 public const string ManifestHash="17b586435d37150da339907866e6c59862dacbab196533de72e13d83d804175a";
 public const string PayloadHash="49e016efc2de73a920be392b150fec4ca2515bb86a1b01548a51ad3ae5d0577e";
 public const string DataName="ACE8Thai_Setup_Data";
 public static readonly JavaScriptSerializer Json=new JavaScriptSerializer{MaxJsonLength=4194304};
 public static readonly Manifest M=LoadManifest();
 public static string Hash(byte[] b){using(var h=SHA256.Create())return BitConverter.ToString(h.ComputeHash(b)).Replace("-","").ToLowerInvariant();}
 public static string HashFile(string p){using(var h=SHA256.Create())using(var f=new FileStream(p,FileMode.Open,FileAccess.Read,FileShare.Read))return BitConverter.ToString(h.ComputeHash(f)).Replace("-","").ToLowerInvariant();}
 public static byte[] Resource(string name){using(var s=Assembly.GetExecutingAssembly().GetManifestResourceStream(name)){if(s==null)throw new IOException("ข้อมูลติดตั้งไม่ครบ");using(var m=new MemoryStream()){s.CopyTo(m);return m.ToArray();}}}
 static Manifest LoadManifest(){var b=Resource("ACE8.Manifest");if(Hash(b)!=ManifestHash)throw new IOException("ข้อมูลกำกับไม่ตรงรุ่น");var m=Json.Deserialize<Manifest>(Encoding.UTF8.GetString(b));if(m.schema!=1||m.files.Length!=18)throw new IOException("ข้อมูลกำกับไม่รองรับ");var seen=new HashSet<string>(StringComparer.OrdinalIgnoreCase);foreach(var e in m.files){Relative(e.path);if(!seen.Add(e.path)||e.bytes<0||e.bytes>134217728||!ValidHash(e.sha256)||e.known==null||e.known.Any(x=>!ValidHash(x)))throw new IOException("รายการติดตั้งไม่ถูกต้อง");}return m;}
 static bool ValidHash(string s){return s!=null&&System.Text.RegularExpressions.Regex.IsMatch(s,"^[0-9a-f]{64}$");}
 public static void Relative(string p){if(String.IsNullOrWhiteSpace(p)||Path.IsPathRooted(p)||p.IndexOfAny(new[]{':','\\','*','?','<','>','|','"'})>=0||p.Split('/').Any(x=>x==""||x=="."||x==".."||x.EndsWith(".")||x.EndsWith(" ")))throw new IOException("พาธนอกขอบเขตม็อด");}
 public static string PathFor(string root,string rel){Relative(rel);root=Path.GetFullPath(root).TrimEnd('\\','/');var p=Path.GetFullPath(Path.Combine(root,rel.Replace('/',Path.DirectorySeparatorChar)));if(!p.StartsWith(root+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))throw new IOException("พาธนอกโฟลเดอร์เกม");for(var x=p;x!=null;x=Path.GetDirectoryName(x)){if((File.Exists(x)||Directory.Exists(x))&&(File.GetAttributes(x)&FileAttributes.ReparsePoint)!=0)throw new IOException("ไม่รองรับโฟลเดอร์ลิงก์: "+x);if(String.Equals(x,root,StringComparison.OrdinalIgnoreCase))break;}return p;}
 public static bool SpaceEnough(long available,long required){return available>=required;}
 public static void Closed(){if(Process.GetProcessesByName("AceCombat8").Length!=0||Process.GetProcessesByName("start_protected_game").Length!=0)throw new IOException("กรุณาปิดเกมก่อนติดตั้งหรือถอนม็อด");}
 public static string VerifyGame(string input){if(String.IsNullOrWhiteSpace(input))throw new IOException("เลือกโฟลเดอร์เกมก่อน");var root=Path.GetFullPath(input).TrimEnd('\\','/');var exe=PathFor(root,"Game/Binaries/Win64/AceCombat8.exe");if(!File.Exists(exe)||HashFile(exe)!=M.exeHash)throw new IOException("รุ่นเกมไม่ตรงกับ Steam Build 25201480 ที่รองรับ");var bootstrap=PathFor(root,"start_protected_game.exe");if(!File.Exists(bootstrap)||HashFile(bootstrap)!=M.bootstrapHash)throw new IOException("ตัวเปิดเกมต้นฉบับไม่ตรงรุ่น");var settings=PathFor(root,"EasyAntiCheat/Settings.json");if(!File.Exists(settings)||HashFile(settings)!=M.settingsHash)throw new IOException("Settings.json ต้นฉบับไม่ตรงรุ่น กรุณาตรวจไฟล์เกม");return root;}
 public static Dictionary<string,byte[]> Payload(){var compressed=Resource("ACE8.Payload");if(Hash(compressed)!=PayloadHash)throw new IOException("ข้อมูลม็อดเสียหาย");var result=new Dictionary<string,byte[]>(StringComparer.OrdinalIgnoreCase);using(var mem=new MemoryStream(compressed))using(var gz=new GZipStream(mem,CompressionMode.Decompress))using(var br=new BinaryReader(gz,Encoding.UTF8)){if(Encoding.ASCII.GetString(br.ReadBytes(8))!="ACE8DAT1"||br.ReadInt32()!=M.files.Length)throw new IOException("รูปแบบข้อมูลไม่รองรับ");foreach(var e in M.files){int length=br.ReadInt32();if(length<1||length>2048)throw new IOException("ชื่อไฟล์ไม่ถูกต้อง");string name=Encoding.UTF8.GetString(br.ReadBytes(length));long size=br.ReadInt64();if(name!=e.path||size!=e.bytes)throw new IOException("ลำดับข้อมูลไม่ตรง");var b=br.ReadBytes(checked((int)size));if(b.Length!=size||Hash(b)!=e.sha256)throw new IOException("แฮชข้อมูลไม่ตรง: "+e.path);result.Add(name,b);}if(gz.ReadByte()!=-1)throw new IOException("มีข้อมูลส่วนเกิน");}return result;}
 static void Durable(string p,byte[] b){Directory.CreateDirectory(Path.GetDirectoryName(p));using(var f=new FileStream(p,FileMode.CreateNew,FileAccess.Write,FileShare.None)){f.Write(b,0,b.Length);f.Flush(true);}}
 static void Atomic(string p,byte[] b,string temporaryDirectory=null){Directory.CreateDirectory(Path.GetDirectoryName(p));var tmp=(temporaryDirectory==null?p:Path.Combine(temporaryDirectory,Path.GetFileName(p)))+".ace8-"+Guid.NewGuid().ToString("N")+".tmp";Durable(tmp,b);try{if(File.Exists(p))File.Replace(tmp,p,null);else File.Move(tmp,p);}finally{if(File.Exists(tmp))File.Delete(tmp);}}
 static void AtomicJson(string p,object v){Atomic(p,Encoding.UTF8.GetBytes(Json.Serialize(v)));}
 static string CurrentHash(string p){return File.Exists(p)?HashFile(p):null;}
 static bool Owned(Entry e,string hash){return hash!=null&&(hash==e.sha256||e.known.Contains(hash));}
 static void Log(string data,string text){using(var f=new FileStream(PathFor(data,"install.log"),FileMode.Append,FileAccess.Write,FileShare.Read)){var b=Encoding.UTF8.GetBytes(DateTimeOffset.Now.ToString("o")+" "+text+"\r\n");f.Write(b,0,b.Length);f.Flush(true);}}
 static void Recover(string root,string data){var path=PathFor(data,"pending.json");if(!File.Exists(path))return;var p=Json.Deserialize<Pending>(File.ReadAllText(path,Encoding.UTF8));if(p.schema!=1||p.root!=root||(p.action!="install"&&p.action!="uninstall")||!System.Text.RegularExpressions.Regex.IsMatch(p.transaction??"","^[a-f0-9]{32}$")||p.before==null||p.before.Length!=M.files.Length||p.settingsHash!=M.settingsHash)throw new IOException("ข้อมูลกู้คืนไม่ถูกต้อง");var tx=PathFor(data,"transactions/"+p.transaction);for(int i=0;i<p.before.Length;i++){var r=p.before[i];var e=M.files[i];if(r.path!=e.path||r.present&&!Owned(e,r.hash)||!r.present&&r.hash!=null)throw new IOException("ข้อมูลกู้คืนนอกขอบเขต");if(r.present&&HashFile(PathFor(tx,"before/"+i+".bin"))!=r.hash)throw new IOException("สำรองเสียหาย หยุดก่อนเขียน");string current=CurrentHash(PathFor(root,r.path));string after=p.action=="install"?e.sha256:null;if(current!=r.hash&&current!=after)throw new IOException("ไฟล์เปลี่ยนจากภายนอก ไม่เขียนทับ: "+r.path);}if(HashFile(PathFor(tx,"Settings.bin"))!=M.settingsHash)throw new IOException("สำรอง Settings เสียหาย");Closed();for(int i=0;i<p.before.Length;i++){var r=p.before[i];var dest=PathFor(root,r.path);if(r.present)Atomic(dest,File.ReadAllBytes(PathFor(tx,"before/"+i+".bin")),PathFor(tx,"recovery"));else if(File.Exists(dest))File.Delete(dest);}var receipt=PathFor(data,"installed.json");if(p.previousReceipt!=null)Atomic(receipt,Encoding.UTF8.GetBytes(p.previousReceipt));else if(File.Exists(receipt))File.Delete(receipt);File.Delete(path);Log(data,"RECOVERY VERIFIED; original target states restored; Settings unchanged");}
 public static void Install(string root){Change(root,true);}
 public static void Uninstall(string root){Change(root,false);}
 static void Change(string input,bool installing){Closed();var root=VerifyGame(input);var mods=PathFor(root,"Game/Binaries/Win64/UE4SS/Mods");if(Directory.Exists(mods))foreach(var d in Directory.GetDirectories(mods))if(!String.Equals(Path.GetFileName(d),"ACE8ThaiProbe",StringComparison.OrdinalIgnoreCase))throw new IOException("พบม็อด UE4SS อื่น หยุดเพื่อไม่กระทบม็อดนั้น");var blobs=installing?Payload():null;foreach(var e in M.files){var path=PathFor(root,e.path);if(Directory.Exists(path))throw new IOException("ปลายทางเป็นโฟลเดอร์: "+e.path);if(File.Exists(path)){if(!Owned(e,HashFile(path)))throw new IOException("พบไฟล์จากม็อดอื่นหรือไฟล์ที่ไม่รู้จัก ไม่เขียนทับ: "+e.path);if((File.GetAttributes(path)&FileAttributes.ReadOnly)!=0)throw new IOException("ไฟล์เป็น Read-only: "+e.path);}}if(!SpaceEnough(new DriveInfo(Path.GetPathRoot(root)).AvailableFreeSpace,M.requiredSpace))throw new IOException("พื้นที่ว่างไม่พอ ต้องมีประมาณ "+(M.requiredSpace/1048576)+" MB");var data=PathFor(root,DataName);Directory.CreateDirectory(data);using(var mutex=new Mutex(false,"Local\\ACE8Thai-"+Hash(Encoding.UTF8.GetBytes(root.ToUpperInvariant())).Substring(0,24))){bool held=false;try{try{held=mutex.WaitOne(0);}catch(AbandonedMutexException){held=true;}if(!held)throw new IOException("มีตัวติดตั้งอีกหน้าต่างกำลังทำงาน");using(var fileLock=new FileStream(PathFor(data,"lock"),FileMode.OpenOrCreate,FileAccess.ReadWrite,FileShare.None)){Recover(root,data);if(installing&&File.Exists(PathFor(data,"installed.json"))&&M.files.All(e=>CurrentHash(PathFor(root,e.path))==e.sha256)){Log(data,"Already installed; no changes");return;}if(!installing&&M.files.All(e=>!File.Exists(PathFor(root,e.path)))){Log(data,"Already uninstalled; no changes");return;}foreach(var e in M.files){var h=CurrentHash(PathFor(root,e.path));if(h!=null&&!Owned(e,h))throw new IOException("ไฟล์เปลี่ยนก่อนสำรอง: "+e.path);}var id=Guid.NewGuid().ToString("N");var tx=PathFor(data,"transactions/"+id);Directory.CreateDirectory(tx);var states=new List<Before>();for(int i=0;i<M.files.Length;i++){var e=M.files[i];var f=PathFor(root,e.path);var b=File.Exists(f)?File.ReadAllBytes(f):null;var r=new Before{path=e.path,present=b!=null,hash=b==null?null:Hash(b)};if(b!=null){var backup=PathFor(tx,"before/"+i+".bin");Durable(backup,b);if(HashFile(backup)!=r.hash)throw new IOException("ตรวจสำรองไม่ผ่าน");File.SetAttributes(backup,File.GetAttributes(backup)|FileAttributes.ReadOnly);}states.Add(r);}var settings=File.ReadAllBytes(PathFor(root,"EasyAntiCheat/Settings.json"));if(Hash(settings)!=M.settingsHash)throw new IOException("Settings เปลี่ยนระหว่างติดตั้ง");var sf=PathFor(tx,"Settings.bin");Durable(sf,settings);if(HashFile(sf)!=M.settingsHash)throw new IOException("ตรวจสำรอง Settings ไม่ผ่าน");File.SetAttributes(sf,FileAttributes.ReadOnly);var receipt=PathFor(data,"installed.json");var p=new Pending{root=root,action=installing?"install":"uninstall",transaction=id,before=states.ToArray(),settingsHash=M.settingsHash,previousReceipt=File.Exists(receipt)?File.ReadAllText(receipt,Encoding.UTF8):null};var checkpoint=PathFor(tx,"checkpoint.json");AtomicJson(checkpoint,p);File.SetAttributes(checkpoint,FileAttributes.ReadOnly);AtomicJson(PathFor(data,"pending.json"),p);Log(data,"CHECKPOINT VERIFIED BEFORE WRITE: "+id+"; "+states.Count+" authored states plus original Settings read-back verified/read-only");Closed();for(int i=0;i<states.Count;i++)if(CurrentHash(PathFor(root,states[i].path))!=states[i].hash)throw new IOException("ไฟล์เปลี่ยนระหว่างสำรอง");try{foreach(var e in M.files){var dest=PathFor(root,e.path);if(installing){Atomic(dest,blobs[e.path],PathFor(tx,"staging"));if(HashFile(dest)!=e.sha256)throw new IOException("ตรวจหลังติดตั้งไม่ผ่าน");}else if(File.Exists(dest))File.Delete(dest);}if(HashFile(PathFor(root,"EasyAntiCheat/Settings.json"))!=M.settingsHash)throw new IOException("Settings เปลี่ยนจากภายนอก");if(installing)AtomicJson(receipt,new{schema=1,root=root,version=M.version,manifest=ManifestHash,files=M.files.Select(e=>new{path=e.path,sha256=e.sha256}).ToArray()});else if(File.Exists(receipt))File.Delete(receipt);File.Delete(PathFor(data,"pending.json"));Log(data,installing?"INSTALL VERIFIED; no game launched":"UNINSTALL VERIFIED; only known mod files removed; original game files unchanged");}catch{Recover(root,data);throw;}}}finally{if(held)mutex.ReleaseMutex();}}}
 public static void Export(string directory){var root=Path.GetFullPath(directory);Directory.CreateDirectory(root);foreach(var pair in new[]{new[]{"manifest.json","ACE8.Manifest"},new[]{"payload.dat.gz","ACE8.Payload"},new[]{"Header.jpg","THub.ACE8.Header"},new[]{"Program.ico","THub.ACE8.ProgramIcon"}}){var p=PathFor(root,pair[0]);if(File.Exists(p))throw new IOException("ไม่ทับไฟล์ที่มีอยู่: "+pair[0]);File.WriteAllBytes(p,Resource(pair[1]));}}
}}
